def shapes(g):
    from scipy.ndimage import label
    import numpy as np
    out={}
    for c in set(v for r in g for v in r if v):
        m=np.array(g)==c
        lab,n=label(m)
        for k in range(1,n+1):
            ys,xs=np.where(lab==k)
            out.setdefault(c,[]).append((list(zip(ys.tolist(),xs.tolist()))))
    return out
